+      color: var(--text);
+      cursor: pointer;
+      padding: 20px 22px;
+      display: flex;
+      align-items: center;
+      justify-content: space-between;
+      gap: 16px;
+      text-align: left;
+      font: inherit;
+      font-weight: 650;
+      line-height: 1.35;
+    }
+
+    .question:focus-visible {
+      outline: 3px solid rgba(138, 180, 255, 0.7);
+      outline-offset: -3px;
+    }
+
+    .question:hover {
+      background: rgba(255, 255, 255, 0.03);
+    }
+
+    .question .icon {
+      flex: none;
+      width: 34px;
+      height: 34px;
+      border-radius: 999px;
+      display: grid;
+      place-items: center;
+      background: rgba(138, 180, 255, 0.12);
+      color: var(--accent);
+      transition: transform 0.2s ease, background 0.2s ease;
+    }
+
+    .example[data-open="true"] .question .icon {
+      transform: rotate(45deg);
+      background: rgba(246, 193, 119, 0.14);
+    }
+
+    .details {
+      padding: 0 22px 20px;
+      color: var(--muted);
+      line-height: 1.7;
+    }
+
+    .details p {
+      margin: 0;
+    }
+
+    .details[hidden] {
+      display: none;
+    }
+
+    @media (max-width: 640px) {
+      .page {
+        padding: 22px;
+        border-radius: 20px;
+      }
+
+      .question,
+      .details {
+        padding-left: 18px;
+        padding-right: 18px;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main class="page">
+    <p class="eyebrow">Frequently asked questions</p>
+    <h1>All about cats</h1>
+    <p class="intro">
+      Curious about cats? Tap a question to reveal the answer. Each response starts collapsed so you can scan the page quickly.
+    </p>
+
+    <section class="faq" aria-label="Cat FAQ">
+      <div class="example" data-open="false">
+        <button class="question" type="button" aria-expanded="false" aria-controls="faq-1">
